/* ============================================
   EMPLOYEE MANAGEMENT — FlowJob
   Time clock, certifications, scheduling
   ============================================ */
const EmployeeManagement = (() => {
  // Certification types
  const CERT_TYPES = {
    plumbing_license: { name: 'Plumbing License', renewalYears: 3, icon: '🔧' },
    backflow_prevention: { name: 'Backflow Prevention', renewalYears: 3, icon: '🔄' },
    gas_fitting: { name: 'Gas Fitting License', renewalYears: 3, icon: '🔥' },
    master_plumber: { name: 'Master Plumber', renewalYears: 5, icon: '👨‍🔧' },
    osha_10: { name: 'OSHA 10-Hour', renewalYears: 5, icon: '🦺' },
    osha_30: { name: 'OSHA 30-Hour', renewalYears: 5, icon: '🦺' },
    epa_608: { name: 'EPA 608 Certification', renewalYears: 5, icon: '❄️' },
    first_aid: { name: 'First Aid/CPR', renewalYears: 2, icon: '🩹' },
    cdl: { name: 'CDL License', renewalYears: 5, icon: '🚛' },
    hazmat: { name: 'HAZMAT Handling', renewalYears: 3, icon: '☢️' }
  };

  // Clock in
  const clockIn = (techId, jobId = null, location = null) => {
    const tech = App.state.employees?.find(e => e.id === techId);
    if (!tech) {
      showToast('Technician not found', 'error');
      return false;
    }
    // Check if already clocked in
    const activeEntry = (App.state.timeEntries || []).find(e => e.techId === techId && !e.clockOut);
    if (activeEntry) {
      showToast('Already clocked in', 'warning');
      return false;
    }
    if (!App.state.timeEntries) App.state.timeEntries = [];
    App.state.timeEntries.push({
      id: Date.now(),
      techId: techId,
      techName: tech.name,
      jobId: jobId,
      clockIn: new Date().toISOString(),
      clockOut: null,
      location: location,
      breakMinutes: 0,
      notes: ''
    });
    tech.status = 'clocked_in';
    tech.currentJobId = jobId;
    App.saveState();
    showToast(`${tech.name} clocked in`, 'success');
    return true;
  };

  // Clock out
  const clockOut = (techId) => {
    const entry = (App.state.timeEntries || []).find(e => e.techId === techId && !e.clockOut);
    if (!entry) {
      showToast('No active clock-in found', 'warning');
      return false;
    }
    entry.clockOut = new Date().toISOString();
    const clockInTime = new Date(entry.clockIn);
    const clockOutTime = new Date(entry.clockOut);
    entry.totalMinutes = Math.round((clockOutTime - clockInTime) / 60000) - (entry.breakMinutes || 0);
    entry.totalHours = (entry.totalMinutes / 60).toFixed(2);
    const tech = App.state.employees?.find(e => e.id === techId);
    if (tech) {
      tech.status = 'clocked_out';
      tech.currentJobId = null;
    }
    App.saveState();
    showToast(`${tech?.name || 'Technician'} clocked out (${entry.totalHours}h)`, 'success');
    return entry;
  };

  // Get active employees
  const getActive = () => {
    return (App.state.employees || []).filter(e => e.status === 'active' || e.status === 'clocked_in');
  };

  // Get time entries for date range
  const getTimeEntries = (startDate, endDate, techId = null) => {
    return (App.state.timeEntries || []).filter(e => {
      const entryDate = new Date(e.clockIn);
      const matchesDate = entryDate >= new Date(startDate) && entryDate <= new Date(endDate + 'T23:59:59');
      const matchesTech = !techId || e.techId === techId;
      return matchesDate && matchesTech;
    });
  };

  // Calculate hours for period
  const calculateHours = (startDate, endDate, techId = null) => {
    const entries = getTimeEntries(startDate, endDate, techId);
    const byTech = {};
    entries.forEach(e => {
      if (!byTech[e.techId]) {
        byTech[e.techId] = { techName: e.techName, totalMinutes: 0, entries: 0 };
      }
      byTech[e.techId].totalMinutes += e.totalMinutes || 0;
      byTech[e.techId].entries++;
    });
    Object.values(byTech).forEach(t => {
      t.totalHours = (t.totalMinutes / 60).toFixed(2);
      t.regularHours = Math.min(parseFloat(t.totalHours), 40).toFixed(2);
      t.overtimeHours = Math.max(0, parseFloat(t.totalHours) - 40).toFixed(2);
    });
    return byTech;
  };

  // Add certification
  const addCertification = (techId, cert) => {
    const tech = App.state.employees?.find(e => e.id === techId);
    if (!tech) return false;
    if (!tech.certifications) tech.certifications = [];
    tech.certifications.push({
      id: Date.now(),
      type: cert.type,
      number: cert.number,
      issued: cert.issued,
      expires: cert.expires,
      issuer: cert.issuer,
      notes: cert.notes
    });
    App.saveState();
    showToast('Certification added', 'success');
    return true;
  };

  // Get expiring certifications
  const getExpiringCertifications = (daysAhead = 30) => {
    const employees = App.state.employees || [];
    const expiring = [];
    const futureDate = new Date();
    futureDate.setDate(futureDate.getDate() + daysAhead);
    employees.forEach(tech => {
      (tech.certifications || []).forEach(cert => {
        const expires = new Date(cert.expires);
        if (expires <= futureDate) {
          expiring.push({
            techId: tech.id,
            techName: tech.name,
            certType: cert.type,
            certName: CERT_TYPES[cert.type]?.name || cert.type,
            expires: cert.expires,
            daysUntil: Math.ceil((expires - Date.now()) / 86400000)
          });
        }
      });
    });
    return expiring.sort((a,b) => a.daysUntil - b.daysUntil);
  };

  // Add employee
  const addEmployee = (data) => {
    if (!App.state.employees) App.state.employees = [];
    const existing = App.state.employees.find(e => e.name === data.name);
    if (existing) {
      showToast('Employee already exists', 'warning');
      return false;
    }
    App.state.employees.push({
      id: Date.now(),
      name: data.name,
      phone: data.phone,
      email: data.email,
      role: data.role || 'technician',
      status: 'active',
      hourlyRate: data.hourlyRate || 0,
      startDate: data.startDate || new Date().toISOString().split('T')[0],
      certifications: [],
      currentJobId: null,
      clockedIn: false
    });
    App.saveState();
    showToast(`${data.name} added to team`, 'success');
    return true;
  };

  // Update employee
  const updateEmployee = (techId, updates) => {
    const tech = App.state.employees?.find(e => e.id === techId);
    if (!tech) return false;
    Object.assign(tech, updates);
    App.saveState();
    return true;
  };

  // Remove employee
  const removeEmployee = (techId) => {
    const index = (App.state.employees || []).findIndex(e => e.id === techId);
    if (index === -1) return false;
    App.state.employees.splice(index, 1);
    App.saveState();
    showToast('Employee removed', 'success');
    return true;
  };

  // Get stats
  const getStats = () => {
    const employees = App.state.employees || [];
    const entries = App.state.timeEntries || [];
    const today = new Date().toISOString().split('T')[0];
    const todayEntries = entries.filter(e => e.clockIn.startsWith(today));
    return {
      totalEmployees: employees.length,
      activeEmployees: employees.filter(e => e.status === 'active').length,
      clockedIn: employees.filter(e => e.status === 'clocked_in').length,
      todayHours: todayEntries.reduce((sum, e) => sum + (e.totalHours ? parseFloat(e.totalHours) : 0), 0).toFixed(1),
      expiringCerts: getExpiringCertifications(30).length
    };
  };

  // Render settings
  const renderSettings = () => {
    const stats = getStats();
    const employees = App.state.employees || [];
    return `
      <div class="glass-card p-6 mb-6">
        <h3 class="text-lg font-bold text-gold-400 mb-4">👷 Employee Management</h3>
        <div class="grid grid-cols-2 md:grid-cols-4 gap-4 mb-4">
          <div class="p-4 rounded-xl text-center" style="background:rgba(255,255,255,0.05)">
            <p class="text-3xl font-bold text-gold-400">${stats.totalEmployees}</p>
            <p class="text-sm text-gray-400">Total Staff</p>
          </div>
          <div class="p-4 rounded-xl text-center" style="background:rgba(255,255,255,0.05)">
            <p class="text-3xl font-bold text-green-400">${stats.clockedIn}</p>
            <p class="text-sm text-gray-400">Clocked In</p>
          </div>
          <div class="p-4 rounded-xl text-center" style="background:rgba(255,255,255,0.05)">
            <p class="text-3xl font-bold text-blue-400">${stats.todayHours}h</p>
            <p class="text-sm text-gray-400">Today's Hours</p>
          </div>
          <div class="p-4 rounded-xl text-center" style="background:rgba(255,255,255,0.05)">
            <p class="text-3xl font-bold text-yellow-400">${stats.expiringCerts}</p>
            <p class="text-sm text-gray-400">Expiring Certs</p>
          </div>
        </div>
        <div class="mb-4">
          <h4 class="font-semibold mb-2">Team Members</h4>
          <div class="space-y-2 max-h-48 overflow-y-auto">
            ${employees.length === 0 ? '<p class="text-sm text-gray-400">No employees added yet</p>' :
              employees.map(e => `
                <div class="flex items-center justify-between p-3 rounded-lg" style="background:rgba(255,255,255,0.05)">
                  <div>
                    <p class="font-semibold">${App.esc(e.name)}</p>
                    <p class="text-xs text-gray-400">${e.role} • ${e.status === 'clocked_in' ? '🟢 Clocked In' : '⚪ Off'}</p>
                  </div>
                  <div class="flex gap-1">
                    ${e.status !== 'clocked_in' ?
                      `<button onclick="EmployeeManagement.clockIn(${e.id})" class="btn btn-primary text-xs px-2 py-1">In</button>` :
                      `<button onclick="EmployeeManagement.clockOut(${e.id})" class="btn btn-secondary text-xs px-2 py-1">Out</button>`
                    }
                  </div>
                </div>
              `).join('')}
          </div>
        </div>
        <button onclick="EmployeeManagement.showAddForm()" class="btn btn-primary w-full py-2">
          ➕ Add Team Member
        </button>
      </div>
    `;
  };

  // Show add form
  const showAddForm = () => {
    let html = `
      <div class="space-y-4">
        <div>
          <label class="block text-sm font-medium mb-1">Name *</label>
          <input type="text" id="emp-name" class="form-input" placeholder="Full name">
        </div>
        <div>
          <label class="block text-sm font-medium mb-1">Phone</label>
          <input type="tel" id="emp-phone" class="form-input" placeholder="Phone number">
        </div>
        <div>
          <label class="block text-sm font-medium mb-1">Email</label>
          <input type="email" id="emp-email" class="form-input" placeholder="Email address">
        </div>
        <div>
          <label class="block text-sm font-medium mb-1">Role</label>
          <select id="emp-role" class="form-input">
            <option value="technician">Technician</option>
            <option value="lead">Lead Technician</option>
            <option value="foreman">Foreman</option>
            <option value="admin">Admin</option>
            <option value="apprentice">Apprentice</option>
          </select>
        </div>
        <div>
          <label class="block text-sm font-medium mb-1">Hourly Rate ($)</label>
          <input type="number" id="emp-rate" class="form-input" placeholder="0.00" step="0.01">
        </div>
        <button onclick="EmployeeManagement.addFromForm()" class="btn btn-primary w-full py-2">
          Add Employee
        </button>
      </div>`;
    App.showModal('Add Team Member', html);
  };

  // Add from form
  const addFromForm = () => {
    const name = document.getElementById('emp-name')?.value?.trim();
    if (!name) {
      showToast('Name is required', 'warning');
      return;
    }
    addEmployee({
      name: name,
      phone: document.getElementById('emp-phone')?.value?.trim(),
      email: document.getElementById('emp-email')?.value?.trim(),
      role: document.getElementById('emp-role')?.value,
      hourlyRate: parseFloat(document.getElementById('emp-rate')?.value) || 0
    });
    App.closeModal();
  };

  return {
    CERT_TYPES,
    clockIn,
    clockOut,
    getActive,
    getTimeEntries,
    calculateHours,
    addCertification,
    getExpiringCertifications,
    addEmployee,
    updateEmployee,
    removeEmployee,
    getStats,
    renderSettings,
    showAddForm,
    addFromForm
  };
})();

modules/insurance-claims.js.content:
/* ============================================
   INSURANCE CLAIMS — FlowJob
   Claim documentation, photos, adjuster comm
   ============================================ */
const InsuranceClaims = (() => {
  // Claim status types
  const STATUS_TYPES = {
    draft: { label: 'Draft', color: 'gray', icon: '📝' },
    submitted: { label: 'Submitted', color: 'blue', icon: '📤' },
    under_review: { label: 'Under Review', color: 'yellow', icon: '🔍' },
    adjuster_assigned: { label: 'Adjuster Assigned', color: 'purple', icon: '👤' },
    inspection_scheduled: { label: 'Inspection Scheduled', color: 'cyan', icon: '📅' },
    approved: { label: 'Approved', color: 'green', icon: '✅' },
    partial_approval: { label: 'Partially Approved', color: 'orange', icon: '⚠️' },
    denied: { label: 'Denied', color: 'red', icon: '❌' },
    paid: { label: 'Paid', color: 'gold', icon: '💰' },
    closed: { label: 'Closed', color: 'gray', icon: '📁' }
  };

  // Damage types
  const DAMAGE_TYPES = {
    water_damage: { name: 'Water Damage', icon: '💧', common: true },
    sewer_backup: { name: 'Sewer Backup', icon: '🚽', common: true },
    frozen_pipes: { name: 'Frozen Pipes', icon: '❄️', common: true },
    burst_pipe: { name: 'Burst Pipe', icon: '💥', common: true },
    water_heater: { name: 'Water Heater Failure', icon: '🔥', common: true },
    flood: { name: 'Flood Damage', icon: '🌊', common: false },
    mold: { name: 'Mold from Plumbing', icon: '🦠', common: false },
    gas_leak: { name: 'Gas Leak', icon: '⚠️', common: false },
    foundation: { name: 'Foundation Leak', icon: '🏗️', common: false },
    other: { name: 'Other', icon: '📋', common: false }
  };

  // Create claim
  const createClaim = (data) => {
    if (!App.state.claims) App.state.claims = [];
    const claim = {
      id: Date.now(),
      jobId: data.jobId,
      customerId: data.customerId,
      customerName: data.customerName,
      insuranceCompany: data.insuranceCompany || '',
      claimNumber: data.claimNumber || '',
      policyNumber: data.policyNumber || '',
      damageType: data.damageType || 'water_damage',
      damageDescription: data.damageDescription || '',
      estimatedCost: data.estimatedCost || 0,
      status: 'draft',
      adjusterName: data.adjusterName || '',
      adjusterPhone: data.adjusterPhone || '',
      adjusterEmail: data.adjusterEmail || '',
      photos: [],
      documents: [],
      communications: [],
      createdAt: new Date().toISOString(),
      updatedAt: new Date().toISOString(),
      notes: data.notes || ''
    };
    App.state.claims.push(claim);
    App.saveState();
    showToast('Claim created', 'success');
    return claim;
  };

  // Update claim
  const updateClaim = (claimId, updates) => {
    const claim = App.state.claims?.find(c => c.id === claimId);
    if (!claim) return false;
    Object.assign(claim, updates, { updatedAt: new Date().toISOString() });
    App.saveState();
    return true;
  };

  // Add photos to claim
  const addPhotos = (claimId, photos) => {
    const claim = App.state.claims?.find(c => c.id === claimId);
    if (!claim) return false;
    photos.forEach(photo => {
      claim.photos.push({
        id: Date.now() + Math.random(),
        url: photo.url || photo,
        caption: photo.caption || '',
        category: photo.category || 'damage',
        timestamp: new Date().toISOString()
      });
    });
    claim.updatedAt = new Date().toISOString();
    App.saveState();
    return true;
  };

  // Add communication
  const addCommunication = (claimId, comm) => {
    const claim = App.state.claims?.find(c => c.id === claimId);
    if (!claim) return false;
    claim.communications.push({
      id: Date.now(),
      type: comm.type || 'phone',
      direction: comm.direction || 'outbound',
      with: comm.with || '',
      subject: comm.subject || '',
      notes: comm.notes || '',
      date: new Date().toISOString()
    });
    claim.updatedAt = new Date().toISOString();
    App.saveState();
    return true;
  };

  // Generate claim report
  const generateReport = (claimId) => {
    const claim = App.state.claims?.find(c => c.id === claimId);
    if (!claim) {
      showToast('Claim not found', 'error');
      return null;
    }
    const settings = App.state.settings || {};
    const customer = App.state.customers?.find(c => c.id === claim.customerId);
    const job = App.state.jobs?.find(j => j.id === claim.jobId);
    const report = `
INSURANCE CLAIM DOCUMENTATION
${settings.businessName || 'FlowJob Plumbing'}
${settings.address || ''}
${settings.phone || ''}

Date: ${new Date().toLocaleDateString()}
Claim #: ${claim.claimNumber || 'Pending'}

═══════════════════════════════════════════

CLAIM INFORMATION

Insurance Company: ${claim.insuranceCompany}
Policy Number: ${claim.policyNumber}
Claim Number: ${claim.claimNumber}
Status: ${STATUS_TYPES[claim.status]?.label || claim.status}

═══════════════════════════════════════════

CUSTOMER INFORMATION

Name: ${customer?.name || claim.customerName || 'N/A'}
Address: ${customer?.address || 'N/A'}
Phone: ${customer?.phone || 'N/A'}
Email: ${customer?.email || 'N/A'}

═══════════════════════════════════════════

DAMAGE ASSESSMENT

Type: ${DAMAGE_TYPES[claim.damageType]?.name || claim.damageType}
Description: ${claim.damageDescription || 'N/A'}

Estimated Repair Cost: $${(claim.estimatedCost || 0).toFixed(2)}

═══════════════════════════════════════════

WORK PERFORMED

Job #: ${job?.id || 'N/A'}
Service: ${job?.title || 'N/A'}
Date: ${job?.date || 'N/A'}
Cost: $${(job?.total || 0).toFixed(2)}

═══════════════════════════════════════════

ADJUSTER CONTACT

Name: ${claim.adjusterName || 'N/A'}
Phone: ${claim.adjusterPhone || 'N/A'}
Email: ${claim.adjusterEmail || 'N/A'}

═══════════════════════════════════════════

PHOTOS: ${claim.photos.length} attached
DOCUMENTS: ${claim.documents.length} attached
COMMUNICATIONS: ${claim.communications.length} logged

═══════════════════════════════════════════

NOTES:
${claim.notes || 'None'}

═══════════════════════════════════════════

Prepared by: ${settings.businessName || 'FlowJob Plumbing'}
Date: ${new Date().toLocaleDateString()}
`;
    // Download as text
    download(report, `FlowJob_Claim_${claim.claimNumber || claim.id}.txt`, 'text/plain');
    return report;
  };

  // Get stats
  const getStats = () => {
    const claims = App.state.claims || [];
    return {
      total: claims.length,
      active: claims.filter(c => !['closed', 'paid', 'denied'].includes(c.status)).length,
      approved: claims.filter(c => ['approved', 'partial_approval', 'paid'].includes(c.status)).length,
      totalValue: claims.reduce((sum, c) => sum + (c.estimatedCost || 0), 0)
    };
  };

  // Render settings
  const renderSettings = () => {
    const stats = getStats();
    const claims = App.state.claims || [];
    return `
      <div class="glass-card p-6 mb-6">
        <h3 class="text-lg font-bold text-gold-400 mb-4">📸 Insurance Claims</h3>
        <div class="grid grid-cols-2 md:grid-cols-4 gap-4 mb-4">
          <div class="p-4 rounded-xl text-center" style="background:rgba(255,255,255,0.05)">
            <p class="text-3xl font-bold text-gold-400">${stats.total}</p>
            <p class="text-sm text-gray-400">Total Claims</p>
          </div>
          <div class="p-4 rounded-xl text-center" style="background:rgba(255,255,255,0.05)">
            <p class="text-3xl font-bold text-blue-400">${stats.active}</p>
            <p class="text-sm text-gray-400">Active</p>
          </div>
          <div class="p-4 rounded-xl text-center" style="background:rgba(255,255,255,0.05)">
            <p class="text-3xl font-bold text-green-400">${stats.approved}</p>
            <p class="text-sm text-gray-400">Approved</p>
          </div>
          <div class="p-4 rounded-xl text-center" style="background:rgba(255,255,255,0.05)">
            <p class="text-3xl font-bold text-purple-400">$${stats.totalValue.toFixed(0)}</p>
            <p class="text-sm text-gray-400">Total Value</p>
          </div>
        </div>
        ${claims.length > 0 ? `
          <div class="mb-4 max-h-48 overflow-y-auto">
            ${claims.slice(0, 10).map(c => `
              <div class="flex items-center justify-between p-3 rounded-lg mb-2" style="background:rgba(255,255,255,0.05)">
                <div>
                  <p class="font-semibold">${DAMAGE_TYPES[c.damageType]?.icon || '📋'} Claim #${c.claimNumber || c.id}</p>
                  <p class="text-xs text-gray-400">${App.esc(c.insuranceCompany)} • $${(c.estimatedCost || 0).toFixed(2)}</p>
                </div>
                <span class="text-xs px-2 py-1 rounded" style="background:rgba(255,255,255,0.1)">${STATUS_TYPES[c.status]?.label || c.status}</span>
              </div>
            `).join('')}
          </div>
        ` : ''}
        <button onclick="InsuranceClaims.showCreateForm()" class="btn btn-primary w-full py-2">
          ➕ New Insurance Claim
        </button>
      </div>
    `;
  };

  // Show create form
  const showCreateForm = () => {
    const jobs = App.state.jobs || [];
    const customers = App.state.customers || [];
    let html = `
      <div class="space-y-4">
        <div>
          <label class="block text-sm font-medium mb-1">Insurance Company *</label>
          <input type="text" id="claim-insurance" class="form-input" placeholder="e.g., State Farm, Allstate">
        </div>
        <div>
          <label class="block text-sm font-medium mb-1">Claim Number</label>
          <input type="text" id="claim-number" class="form-input" placeholder="Claim #">
        </div>
        <div>
          <label class="block text-sm font-medium mb-1">Customer</label>
          <select id="claim-customer" class="form-input">
            <option value="">Select customer...</option>
            ${customers.map(c => `<option value="${c.id}">${App.esc(c.name)}</option>`).join('')}
          </select>
        </div>
        <div>
          <label class="block text-sm font-medium mb-1">Related Job</label>
          <select id="claim-job" class="form-input">
            <option value="">Select job...</option>
            ${jobs.map(j => `<option value="${j.id}">#${j.id} - ${App.esc(j.title)}</option>`).join('')}
          </select>
        </div>
        <div>
          <label class="block text-sm font-medium mb-1">Damage Type</label>
          <select id="claim-damage" class="form-input">
            ${Object.entries(DAMAGE_TYPES).map(([k,v]) => `<option value="${k}">${v.icon} ${v.name}</option>`).join('')}
          </select>
        </div>
        <div>
          <label class="block text-sm font-medium mb-1">Estimated Cost ($)</label>
          <input type="number" id="claim-cost" class="form-input" placeholder="0.00" step="0.01">
        </div>
        <div>
          <label class="block text-sm font-medium mb-1">Description</label>
          <textarea id="claim-desc" class="form-input" rows="3" placeholder="Describe the damage..."></textarea>
        </div>
        <button onclick="InsuranceClaims.createFromForm()" class="btn btn-primary w-full py-2">
          Create Claim
        </button>
      </div>`;
    App.showModal('New Insurance Claim', html);
  };

  // Create from form
  const createFromForm = () => {
    const insurance = document.getElementById('claim-insurance')?.value?.trim();
    if (!insurance) {
      showToast('Insurance company is required', 'warning');
      return;
    }
    const customerId = parseInt(document.getElementById('claim-customer')?.value);
    const customer = App.state.customers?.find(c => c.id === customerId);
    createClaim({
      insuranceCompany: insurance,
      claimNumber: document.getElementById('claim-number')?.value?.trim(),
      customerId: customerId,
      customerName: customer?.name,
      jobId: parseInt(document.getElementById('claim-job')?.value),
      damageType: document.getElementById('claim-damage')?.value,
      estimatedCost: parseFloat(document.getElementById('claim-cost')?.value) || 0,
      damageDescription: document.getElementById('claim-desc')?.value?.trim()
    });
    App.closeModal();
  };

  return {
    STATUS_TYPES,
    DAMAGE_TYPES,
    createClaim,
    updateClaim,
    addPhotos,
    addCommunication,
    generateReport,
    getStats,
    renderSettings,
    showCreateForm,
    createFromForm
  };
})();

modules/job-site-reporter.js.content:
// FlowJob — Job Site Reporter Module
// Photo documentation, damage assessment, PDF reports for insurance claims

const JobSiteReporter = {
  categories: [
    { id: 'before', label: 'Before', icon: '📷' },
    { id: 'during', label: 'During', icon: '🔧' },
    { id: 'after', label: 'After', icon: '✅' },
    { id: 'damage', label: 'Damage', icon: '⚠️' },
    { id: 'materials', label: 'Materials', icon: '📦' },
    { id: 'measurements', label: 'Measurements', icon: '📏' },
    { id: 'code-issues', label: 'Code Issues', icon: '🚫' },
    { id: 'hazards', label: 'Hazards', icon: '☠️' },
  ],

  damageTypes: ['Water Damage', 'Mold', 'Corrosion', 'Crack', 'Blockage', 'Leak', 'Structural', 'Code Violation'],
  severityLevels: ['Minor', 'Moderate', 'Severe', 'Critical'],

  renderReporter() {
    const reports = App.state.photoReports || [];
    const activeReport = App.state.activePhotoReport;

    if (activeReport) {
      return this.renderActiveReport(activeReport);
    }

    return `
      <div class="glass-card p-6">
        <div class="flex justify-between items-center mb-4">
          <h3 class="text-lg font-bold text-gold-400">📸 Photo Reports</h3>
          <button class="btn btn-gold btn-sm" onclick="JobSiteReporter.newReport()">+ New Report</button>
        </div>
        ${reports.length === 0 ?
          '<p class="text-muted text-center p-4">No photo reports yet. Create one to start documenting job sites.</p>' :
          reports.map((r, i) => `
            <div class="flex justify-between items-center p-3 mb-2" style="background:rgba(255,255,255,0.03);border-radius:8px;cursor:pointer;" onclick="JobSiteReporter.openReport(${i})">
              <div>
                <div class="font-bold">${r.title || 'Untitled Report'}</div>
                <div class="text-muted text-sm">${r.customer || 'No customer'} — ${r.date || 'No date'} — ${(r.photos || []).length} photos</div>
              </div>
              <div class="flex gap-2">
                <span class="badge badge-${r.status === 'complete' ? 'success' : 'warning'}">${r.status || 'draft'}</span>
                <button class="btn btn-outline btn-sm" onclick="event.stopPropagation();JobSiteReporter.deleteReport(${i})">🗑️</button>
              </div>
            </div>
          `).join('')}
      </div>
    `;
  },

  renderActiveReport(report) {
    const photos = report.photos || [];
    const grouped = {};
    this.categories.forEach(c => grouped[c.id] = []);
    photos.forEach(p => {
      if (grouped[p.category]) grouped[p.category].push(p);
    });

    return `
      <div class="flex justify-between items-center mb-4">
        <button class="btn btn-outline btn-sm" onclick="JobSiteReporter.closeReport()">← Back to Reports</button>
        <div class="flex gap-2">
          <button class="btn btn-outline btn-sm" onclick="JobSiteReporter.editReportInfo()">✏️ Edit Info</button>
          <button class="btn btn-gold btn-sm" onclick="JobSiteReporter.exportReport()">📄 Export Report</button>
        </div>
      </div>

      <div class="glass-card p-6">
        <h3 class="text-lg font-bold text-gold-400 mb-2">${App.esc(report.title || 'Untitled Report')}</h3>
        <div class="grid grid-cols-2 gap-2 text-sm">
          <div><span class="text-muted">Customer:</span> ${App.esc(report.customer || 'N/A')}</div>
          <div><span class="text-muted">Property:</span> ${App.esc(report.address || 'N/A')}</div>
          <div><span class="text-muted">Date:</span> ${App.esc(report.date || 'N/A')}</div>
          <div><span class="text-muted">Type:</span> ${App.esc(report.jobType || 'N/A')}</div>
          <div><span class="text-muted">Job ID:</span> ${App.esc(report.jobId || 'N/A')}</div>
          <div><span class="text-muted">Technician:</span> ${App.esc(report.technician || 'N/A')}</div>
        </div>
      </div>

      <div class="glass-card p-6">
        <div class="flex justify-between items-center mb-4">
          <h3 class="text-lg font-bold text-gold-400">📷 Photos</h3>
          <button class="btn btn-gold btn-sm" onclick="JobSiteReporter.addPhoto()">+ Add Photo</button>
        </div>

        ${this.categories.map(cat => {
          const catPhotos = grouped[cat.id] || [];
          if (catPhotos.length === 0 && cat.id !== 'before' && cat.id !== 'after' && cat.id !== 'damage') return '';
          return `
            <div class="mb-4">
              <h4 class="font-bold mb-2">${cat.icon} ${cat.label} (${catPhotos.length})</h4>
              ${catPhotos.length === 0 ?
                '<p class="text-muted text-sm">No photos in this category</p>' :
                catPhotos.map((p, pi) => `
                  <div class="p-3 mb-2" style="background:rgba(255,255,255,0.03);border-radius:8px;">
                    <div class="flex justify-between">
                      <div>
                        <div class="font-bold">${App.esc(p.description || 'No description')}</div>
                        <div class="text-muted text-sm">${p.timestamp || ''} ${p.severity ? '— Severity: ' + p.severity : ''} ${p.damageType ? '— ' + p.damageType : ''}</div>
                      </div>
                      <button class="btn btn-outline btn-sm" style="color:#ef4444" onclick="JobSiteReporter.removePhoto(${photos.indexOf(p)})">✕</button>
                    </div>
                  </div>
                `).join('')}
            </div>
          `;
        }).join('')}
      </div>

      ${this.renderDamageSummary(photos)}

      <div class="glass-card p-6">
        <h3 class="text-lg font-bold text-gold-400 mb-2">📝 Notes</h3>
        <textarea id="report-notes" class="form-control" rows="4" placeholder="Additional observations, code issues, safety concerns..."
          onchange="JobSiteReporter.saveNotes(this.value)">${App.esc(report.notes || '')}</textarea>
      </div>
    `;
  },

  renderDamageSummary(photos) {
    const damagePhotos = photos.filter(p => p.category === 'damage');
    if (damagePhotos.length === 0) return '';

    return `
      <div class="glass-card p-6" style="border:2px solid #ef4444;">
        <h3 class="text-lg font-bold mb-4" style="color:#ef4444;">⚠️ Damage Assessment Summary</h3>
        <table class="data-table" style="width:100%;">
          <thead><tr><th>Type</th><th>Severity</th><th>Description</th></tr></thead>
          <tbody>
            ${damagePhotos.map(p => `
              <tr>
                <td>${App.esc(p.damageType || 'Unspecified')}</td>
                <td><span class="badge badge-${p.severity === 'Critical' ? 'danger' : p.severity === 'Severe' ? 'warning' : 'info'}">${App.esc(p.severity || 'N/A')}</span></td>
                <td>${App.esc(p.description || '')}</td>
              </tr>
            `).join('')}
          </tbody>
        </table>
      </div>
    `;
  },

  newReport() {
    const biz = App.getBusinessInfo();
    App.showModal('New Photo Report', `
      <div class="form-grid">
        <div class="form-group"><label>Report Title</label><input id="nr-title" class="form-control" placeholder="e.g., Water Damage - Smith Residence"></div>
        <div class="form-group"><label>Customer</label><input id="nr-customer" class="form-control" placeholder="Customer name"></div>
        <div class="form-group"><label>Property Address</label><input id="nr-address" class="form-control" placeholder="123 Main St"></div>
        <div class="form-group"><label>Date</label><input id="nr-date" class="form-control" type="date" value="${new Date().toISOString().split('T')[0]}"></div>
        <div class="form-group"><label>Job Type</label>
          <select id="nr-type" class="form-control">
            <option value="repair">Repair</option><option value="installation">Installation</option>
            <option value="inspection">Inspection</option><option value="damage-assessment">Damage Assessment</option>
            <option value="insurance-claim">Insurance Claim</option>
          </select>
        </div>
        <div class="form-group"><label>Job ID (optional)</label><input id="nr-jobid" class="form-control" placeholder="JOB-001"></div>
        <div class="form-group"><label>Technician</label><input id="nr-tech" class="form-control" value="${App.esc(biz.contact || '')}"></div>
      </div>
      <button class="btn btn-gold mt-3" onclick="JobSiteReporter.saveNewReport()">Create Report</button>
    `);
  },

  saveNewReport() {
    const report = {
      title: document.getElementById('nr-title')?.value || 'Untitled',
      customer: document.getElementById('nr-customer')?.value || '',
      address: document.getElementById('nr-address')?.value || '',
      date: document.getElementById('nr-date')?.value || new Date().toISOString().split('T')[0],
      jobType: document.getElementById('nr-type')?.value || '',
      jobId: document.getElementById('nr-jobid')?.value || '',
      technician: document.getElementById('nr-tech')?.value || '',
      status: 'draft',
      photos: [],
      notes: '',
      created: new Date().toISOString(),
    };
    const reports = App.state.photoReports || [];
    reports.push(report);
    App.state.photoReports = reports;
    App.state.activePhotoReport = report;
    App.state.activePhotoReportIdx = reports.length - 1;
    App.saveState();
    App.closeModal();
    this.refresh();
    App.toast('Photo report created!', 'success');
  },

  openReport(idx) {
    const reports = App.state.photoReports || [];
    if (!reports[idx]) return;
    App.state.activePhotoReport = reports[idx];
    App.state.activePhotoReportIdx = idx;
    this.refresh();
  },

  closeReport() {
    delete App.state.activePhotoReport;
    delete App.state.activePhotoReportIdx;
    this.refresh();
  },

  addPhoto() {
    App.showModal('Add Photo', `
      <div class="form-grid">
        <div class="form-group"><label>Category</label>
          <select id="ap-category" class="form-control">
            ${this.categories.map(c => `<option value="${c.id}">${c.icon} ${c.label}</option>`).join('')}
          </select>
        </div>
        <div class="form-group"><label>Description</label><input id="ap-desc" class="form-control" placeholder="What does this photo show?"></div>
        <div class="form-group"><label>Timestamp</label><input id="ap-time" class="form-control" type="datetime-local" value="${new Date().toISOString().slice(0, 16)}"></div>
        <div class="form-group" id="ap-damage-fields" style="display:none;">
          <label>Damage Type</label>
          <select id="ap-damage" class="form-control">
            ${this.damageTypes.map(d => `<option value="${d}">${d}</option>`).join('')}
          </select>
        </div>
        <div class="form-group" id="ap-severity-field" style="display:none;">
          <label>Severity</label>
          <select id="ap-severity" class="form-control">
            ${this.severityLevels.map(s => `<option value="${s}">${s}</option>`).join('')}
          </select>
        </div>
      </div>
      <button class="btn btn-gold mt-3" onclick="JobSiteReporter.savePhoto()">Add Photo</button>
    `);

    // Show/hide damage fields based on category
    document.getElementById('ap-category')?.addEventListener('change', (e) => {
      const isDamage = e.target.value === 'damage';
      const df = document.getElementById('ap-damage-fields');
      const sf = document.getElementById('ap-severity-field');
      if (df) df.style.display = isDamage ? 'block' : 'none';
      if (sf) sf.style.display = isDamage ? 'block' : 'none';
    });
  },

  savePhoto() {
    const photo = {
      category: document.getElementById('ap-category')?.value || 'before',
      description: document.getElementById('ap-desc')?.value || '',
      timestamp: document.getElementById('ap-time')?.value || new Date().toISOString(),
      damageType: document.getElementById('ap-damage')?.value || '',
      severity: document.getElementById('ap-severity')?.value || '',
    };
    const report = App.state.activePhotoReport;
    if (!report) return;
    report.photos = report.photos || [];
    report.photos.push(photo);
    this.syncReport(report);
    App.closeModal();
    this.refresh();
    App.toast('Photo added', 'success');
  },

  removePhoto(idx) {
    const report = App.state.activePhotoReport;
    if (!report || !report.photos) return;
    report.photos.splice(idx, 1);
    this.syncReport(report);
    this.refresh();
  },

  saveNotes(val) {
    const report = App.state.activePhotoReport;
    if (!report) return;
    report.notes = val;
    this.syncReport(report);
  },

  editReportInfo() {
    const r = App.state.activePhotoReport;
    if (!r) return;
    App.showModal('Edit Report Info', `
      <div class="form-grid">
        <div class="form-group"><label>Title</label><input id="er-title" class="form-control" value="${App.esc(r.title || '')}"></div>
        <div class="form-group"><label>Customer</label><input id="er-customer" class="form-control" value="${App.esc(r.customer || '')}"></div>
        <div class="form-group"><label>Address</label><input id="er-address" class="form-control" value="${App.esc(r.address || '')}"></div>
        <div class="form-group"><label>Status</label>
          <select id="er-status" class="form-control">
            <option value="draft" ${r.status === 'draft' ? 'selected' : ''}>Draft</option>
            <option value="complete" ${r.status === 'complete' ? 'selected' : ''}>Complete</option>
          </select>
        </div>
      </div>
      <button class="btn btn-gold mt-3" onclick="JobSiteReporter.saveReportInfo()">Save</button>
    `);
  },

  saveReportInfo() {
    const report = App.state.activePhotoReport;
    if (!report) return;
    report.title = document.getElementById('er-title')?.value || report.title;
    report.customer = document.getElementById('er-customer')?.value || report.customer;
    report.address = document.getElementById('er-address')?.value || report.address;
    report.status = document.getElementById('er-status')?.value || report.status;
    this.syncReport(report);
    App.closeModal();
    this.refresh();
    App.toast('Report updated', 'success');
  },

  syncReport(report) {
    const idx = App.state.activePhotoReportIdx;
    if (idx !== undefined && App.state.photoReports) {
      App.state.photoReports[idx] = report;
    }
    App.state.activePhotoReport = report;
    App.saveState();
  },

  exportReport() {
    const r = App.state.activePhotoReport;
    if (!r) return;
    const photos = r.photos || [];
    const grouped = {};
    this.categories.forEach(c => grouped[c.id] = []);
    photos.forEach(p => { if (grouped[p.category]) grouped[p.category].push(p); });

    let html = `
      <p><strong>Customer:</strong> ${App.esc(r.customer || 'N/A')} | <strong>Property:</strong> ${App.esc(r.address || 'N/A')}</p>
      <p><strong>Date:</strong> ${App.esc(r.date || 'N/A')} | <strong>Type:</strong> ${App.esc(r.jobType || 'N/A')} | <strong>Technician:</strong> ${App.esc(r.technician || 'N/A')}</p>
      <hr>`;

    this.categories.forEach(cat => {
      const cp = grouped[cat.id] || [];
      if (cp.length === 0) return;
      html += `<h3>${cat.icon} ${cat.label} Photos</h3><table><thead><tr><th>#</th><th>Description</th><th>Time</th>`;
      if (cat.id === 'damage') html += '<th>Type</th><th>Severity</th>';
      html += '</tr></thead><tbody>';
      cp.forEach((p, i) => {
        html += `<tr><td>${i + 1}</td><td>${App.esc(p.description || '')}</td><td>${App.esc(p.timestamp || '')}</td>`;
        if (cat.id === 'damage') html += `<td>${App.esc(p.damageType || '')}</td><td>${App.esc(p.severity || '')}</td>`;
        html += '</tr>';
      });
      html += '</tbody></table>';
    });

    if (r.notes) html += `<h3>Notes</h3><p>${App.esc(r.notes)}</p>`;

    App.printSection('Job Site Photo Report', html);
  },

  deleteReport(idx) {
    if (!confirm('Delete this report?')) return;
    const reports = App.state.photoReports || [];
    reports.splice(idx, 1);
    App.state.photoReports = reports;
    App.saveState();
    this.refresh();
    App.toast('Report deleted', 'info');
  },

  refresh() {
    const content = document.getElementById('content');
    if (content && window.location.hash === '#photo-report') {
      content.innerHTML = `<div class="page-header"><h2>📸 Job Site Reporter</h2></div>${this.renderReporter()}`;
      App.injectPageIcons();
    }
  },
};

modules/membership-subscription.js.content:
/* ============================================
   MEMBERSHIP & SUBSCRIPTION — FlowJob
   Maintenance plans, recurring billing
   ============================================ */
const MembershipSubscription = (() => {
  // Plan tiers
  const PLAN_TIERS = {
    basic: {
      name: 'Basic Care',
      color: '#6B7280',
      icon: '🔧',
      features: ['Annual inspection', '10% off repairs', 'Priority scheduling']
    },
    premium: {
      name: 'Premium Care',
      color: '#3B82F6',
      icon: '⭐',
      features: ['Bi-annual inspection', '15% off repairs', 'Priority scheduling', 'Free emergency call', 'Water heater flush']
    },
    vip: {
      name: 'VIP Care',
      color: '#FFD700',
      icon: '👑',
      features: ['Quarterly inspection', '20% off repairs', 'Same-day scheduling', '2 free emergency calls', 'Water heater flush', 'Drain cleaning', 'Dedicated technician']
    }
  };

  // Create plan
  const createPlan = (data) => {
    if (!App.state.membershipPlans) App.state.membershipPlans = [];
    const plan = {
      id: Date.now(),
      name: data.name,
      tier: data.tier || 'basic',
      price: data.price || 0,
      interval: data.interval || 'monthly',
      annualPrice: data.annualPrice || (data.price * 12 * 0.9),
      services: data.services || [],
      features: data.features || PLAN_TIERS[data.tier]?.features || [],
      discount: data.discount || (data.tier === 'vip' ? 20 : data.tier === 'premium' ? 15 : 10),
      maxEmergencyCalls: data.maxEmergencyCalls || (data.tier === 'vip' ? 2 : data.tier === 'premium' ? 1 : 0),
      status: 'active',
      createdAt: new Date().toISOString()
    };
    App.state.membershipPlans.push(plan);
    App.saveState();
    showToast('Plan created', 'success');
    return plan;
  };

  // Enroll customer
  const enroll = (customerId, planId, paymentMethod = 'invoice') => {
    const customer = App.state.customers?.find(c => c.id === customerId);
    const plan = App.state.membershipPlans?.find(p => p.id === planId);
    if (!customer || !plan) {
      showToast('Customer or plan not found', 'error');
      return false;
    }
    if (!App.state.memberships) App.state.memberships = [];
    // Check if already enrolled
    const existing = App.state.memberships.find(m => m.customerId === customerId && m.status === 'active');
    if (existing) {
      showToast('Customer already has an active membership', 'warning');
      return false;
    }
    const membership = {
      id: Date.now(),
      customerId: customerId,
      customerName: customer.name,
      planId: planId,
      planName: plan.name,
      tier: plan.tier,
      price: plan.interval === 'annual' ? plan.annualPrice : plan.price,
      interval: plan.interval,
      paymentMethod: paymentMethod,
      startDate: new Date().toISOString(),
      nextBillingDate: calculateNextBilling(plan.interval),
      status: 'active',
      servicesUsed: 0,
      emergencyCallsUsed: 0,
      billingHistory: []
    };
    membership.billingHistory.push({
      date: new Date().toISOString(),
      amount: membership.price,
      status: 'pending',
      method: paymentMethod
    });
    App.state.memberships.push(membership);
    App.saveState();
    showToast(`${customer.name} enrolled in ${plan.name}`, 'success');
    return membership;
  };

  // Cancel membership
  const cancel = (membershipId) => {
    const membership = App.state.memberships?.find(m => m.id === membershipId);
    if (!membership) return false;
    membership.status = 'cancelled';
    membership.cancelledAt = new Date().toISOString();
    App.saveState();
    showToast('Membership cancelled', 'success');
    return true;
  };

  // Process billing (run monthly)
  const processBilling = () => {
    const memberships = App.state.memberships || [];
    const today = new Date();
    let billed = 0;
    memberships.forEach(m => {
      if (m.status !== 'active') return;
      const nextBilling = new Date(m.nextBillingDate);
      if (today >= nextBilling) {
        m.billingHistory.push({
          date: today.toISOString(),
          amount: m.price,
          status: 'pending',
          method: m.paymentMethod
        });
        m.nextBillingDate = calculateNextBilling(m.interval, today);
        billed++;
      }
    });
    if (billed > 0) {
      App.saveState();
      showToast(`${billed} memberships billed`, 'success');
    }
    return billed;
  };

  // Calculate next billing date
  const calculateNextBilling = (interval, fromDate = new Date()) => {
    const date = new Date(fromDate);
    if (interval === 'monthly') {
      date.setMonth(date.getMonth() + 1);
    } else if (interval === 'quarterly') {
      date.setMonth(date.getMonth() + 3);
    } else if (interval === 'annual') {
      date.setFullYear(date.getFullYear() + 1);
    }
    return date.toISOString();
  };

  // Get membership stats
  const getStats = () => {
    const memberships = App.state.memberships || [];
    const active = memberships.filter(m => m.status === 'active');
    const mrr = active.reduce((sum, m) => {
      if (m.interval === 'monthly') return sum + m.price;
      if (m.interval === 'quarterly') return sum + (m.price / 3);
      if (m.interval === 'annual') return sum + (m.price / 12);
      return sum;
    }, 0);
    const arr = mrr * 12;
    const tierBreakdown = { basic: 0, premium: 0, vip: 0 };
    active.forEach(m => { if (tierBreakdown[m.tier] !== undefined) tierBreakdown[m.tier]++; });
    return {
      totalMembers: memberships.length,
      activeMembers: active.length,
      mrr: mrr,
      arr: arr,
      tierBreakdown: tierBreakdown,
      churnRate: memberships.length > 0 ?
        ((memberships.filter(m => m.status === 'cancelled').length / memberships.length) * 100).toFixed(1) : 0
    };
  };

  // Render settings
  const renderSettings = () => {
    const stats = getStats();
    const plans = App.state.membershipPlans || [];
    const memberships = App.state.memberships || [];
    return `
      <div class="glass-card p-6 mb-6">
        <h3 class="text-lg font-bold text-gold-400 mb-4">💳 Membership & Subscription</h3>
        <div class="grid grid-cols-2 md:grid-cols-4 gap-4 mb-4">
          <div class="p-4 rounded-xl text-center" style="background:rgba(255,255,255,0.05)">
            <p class="text-3xl font-bold text-gold-400">${stats.activeMembers}</p>
            <p class="text-sm text-gray-400">Active Members</p>
          </div>
          <div class="p-4 rounded-xl text-center" style="background:rgba(255,255,255,0.05)">
            <p class="text-3xl font-bold text-green-400">$${stats.mrr.toFixed(0)}</p>
            <p class="text-sm text-gray-400">MRR</p>
          </div>
          <div class="p-4 rounded-xl text-center" style="background:rgba(255,255,255,0.05)">
            <p class="text-3xl font-bold text-blue-400">$${stats.arr.toFixed(0)}</p>
            <p class="text-sm text-gray-400">ARR</p>
          </div>
          <div class="p-4 rounded-xl text-center" style="background:rgba(255,255,255,0.05)">
            <p class="text-3xl font-bold text-purple-400">${plans.length}</p>
            <p class="text-sm text-gray-400">Plans</p>
          </div>
        </div>
        <div class="mb-4">
          <h4 class="font-semibold mb-2">Available Plans</h4>
          <div class="grid grid-cols-1 md:grid-cols-3 gap-3">
            ${plans.length === 0 ?
              Object.entries(PLAN_TIERS).map(([key, tier]) => `
                <div class="p-4 rounded-xl text-center" style="background:rgba(255,255,255,0.05);border:1px solid ${tier.color}30">
                  <p class="text-2xl mb-1">${tier.icon}</p>
                  <p class="font-semibold">${tier.name}</p>
                  <p class="text-xs text-gray-400 mt-1">${tier.features.length} features</p>
                </div>
              `).join('') :
              plans.map(p => `
                <div class="p-4 rounded-xl" style="background:rgba(255,255,255,0.05);border:1px solid ${PLAN_TIERS[p.tier]?.color || '#666'}30">
                  <p class="font-semibold">${PLAN_TIERS[p.tier]?.icon || '🔧'} ${App.esc(p.name)}</p>
                  <p class="text-lg font-bold text-gold-400">$${p.price}/${p.interval === 'annual' ? 'yr' : 'mo'}</p>
                  <p class="text-xs text-gray-400">${p.features.length} features</p>
                </div>
              `).join('')}
          </div>
        </div>
        <div class="flex gap-2">
          <button onclick="MembershipSubscription.showCreatePlan()" class="btn btn-primary flex-1 py-2">
            ➕ Create Plan
          </button>
          <button onclick="MembershipSubscription.showEnrollForm()" class="btn btn-secondary flex-1 py-2">
            📝 Enroll Customer
          </button>
        </div>
      </div>
    `;
  };

  // Show create plan form
  const showCreatePlan = () => {
    let html = `
      <div class="space-y-4">
        <div>
          <label class="block text-sm font-medium mb-1">Plan Name *</label>
          <input type="text" id="plan-name" class="form-input" placeholder="e.g., Premium Care">
        </div>
        <div>
          <label class="block text-sm font-medium mb-1">Tier</label>
          <select id="plan-tier" class="form-input">
            ${Object.entries(PLAN_TIERS).map(([k,v]) => `<option value="${k}">${v.icon} ${v.name}</option>`).join('')}
          </select>
        </div>
        <div>
          <label class="block text-sm font-medium mb-1">Price ($)</label>
          <input type="number" id="plan-price" class="form-input" placeholder="29.99" step="0.01">
        </div>
        <div>
          <label class="block text-sm font-medium mb-1">Billing Interval</label>
          <select id="plan-interval" class="form-input">
            <option value="monthly">Monthly</option>
            <option value="quarterly">Quarterly</option>
            <option value="annual">Annual</option>
          </select>
        </div>
        <button onclick="MembershipSubscription.createPlanFromForm()" class="btn btn-primary w-full py-2">
          Create Plan
        </button>
      </div>`;
    App.showModal('Create Membership Plan', html);
  };

  // Create plan from form
  const createPlanFromForm = () => {
    const name = document.getElementById('plan-name')?.value?.trim();
    if (!name) {
      showToast('Plan name is required', 'warning');
      return;
    }
    createPlan({
      name: name,
      tier: document.getElementById('plan-tier')?.value,
      price: parseFloat(document.getElementById('plan-price')?.value) || 0,
      interval: document.getElementById('plan-interval')?.value
    });
    App.closeModal();
  };

  // Show enroll form
  const showEnrollForm = () => {
    const customers = App.state.customers || [];
    const plans = App.state.membershipPlans || [];
    if (plans.length === 0) {
      showToast('Create a plan first', 'warning');
      return;
    }
    let html = `
      <div class="space-y-4">
        <div>
          <label class="block text-sm font-medium mb-1">Customer *</label>
          <select id="enroll-customer" class="form-input">
            <option value="">Select customer...</option>
            ${customers.map(c => `<option value="${c.id}">${App.esc(c.name)}</option>`).join('')}
          </select>
        </div>
        <div>
          <label class="block text-sm font-medium mb-1">Plan *</label>
          <select id="enroll-plan" class="form-input">
            ${plans.map(p => `<option value="${p.id}">${App.esc(p.name)} - $${p.price}/${p.interval === 'annual' ? 'yr' : 'mo'}</option>`).join('')}
          </select>
        </div>
        <div>
          <label class="block text-sm font-medium mb-1">Payment Method</label>
          <select id="enroll-payment" class="form-input">
            <option value="invoice">Invoice</option>
            <option value="card">Credit Card</option>
            <option value="ach">ACH/Bank</option>
          </select>
        </div>
        <button onclick="MembershipSubscription.enrollFromForm()" class="btn btn-primary w-full py-2">
          Enroll Customer
        </button>
      </div>`;
    App.showModal('Enroll Customer', html);
  };

  // Enroll from form
  const enrollFromForm = () => {
    const customerId = parseInt(document.getElementById('enroll-customer')?.value);
    const planId = parseInt(document.getElementById('enroll-plan')?.value);
    const payment = document.getElementById('enroll-payment')?.value;
    if (!customerId || !planId) {
      showToast('Please select customer and plan', 'warning');
      return;
    }
    enroll(customerId, planId, payment);
    App.closeModal();
  };

  return {
    PLAN_TIERS,
    createPlan,
    enroll,
    cancel,
    processBilling,
    getStats,
    renderSettings,
    showCreatePlan,
    createPlanFromForm,
    showEnrollForm,
    enrollFromForm
  };
})();

