/* ============================================
   PRICE BOOK MANAGER — FlowJob
   Dynamic pricing, materials, labor rates
   ============================================ */
const PriceBookManager = (() => {
  // Default material categories
  const MATERIAL_CATEGORIES = {
    pipe: { name: 'Pipe & Fittings', icon: '🔧' },
    fixture: { name: 'Fixtures', icon: '🚿' },
    water_heater: { name: 'Water Heaters', icon: '🔥' },
    valve: { name: 'Valves', icon: '⚙️' },
    pump: { name: 'Pumps', icon: '💧' },
    sewer: { name: 'Sewer & Drain', icon: '🚽' },
    gas: { name: 'Gas Fittings', icon: '🔥' },
    tools: { name: 'Tools & Supplies', icon: '🔨' },
    chemical: { name: 'Chemicals', icon: '🧪' },
    other: { name: 'Other', icon: '📦' }
  };

  // Labor rate tiers
  const LABOR_TIERS = {
    standard: { name: 'Standard', multiplier: 1.0, description: 'Mon-Fri, 8am-5pm' },
    overtime: { name: 'Overtime', multiplier: 1.5, description: 'Evenings, weekends' },
    emergency: { name: 'Emergency', multiplier: 2.0, description: 'Same-day, after-hours' },
    holiday: { name: 'Holiday', multiplier: 2.5, description: 'Holidays' }
  };

  // Add material
  const addMaterial = (data) => {
    if (!App.state.materials) App.state.materials = [];
    const existing = App.state.materials.find(m => m.sku === data.sku);
    if (existing) {
      showToast('SKU already exists', 'warning');
      return false;
    }
    App.state.materials.push({
      id: Date.now(),
      sku: data.sku || generateSKU(data.name),
      name: data.name,
      category: data.category || 'other',
      unitCost: data.unitCost || 0,
      markup: data.markup || 2.0,
      sellPrice: data.sellPrice || (data.unitCost * (data.markup || 2.0)),
      unit: data.unit || 'ea',
      vendor: data.vendor || '',
      vendorSku: data.vendorSku || '',
      inStock: data.inStock || 0,
      reorderPoint: data.reorderPoint || 5,
      leadTimeDays: data.leadTimeDays || 3,
      lastUpdated: new Date().toISOString()
    });
    App.saveState();
    return true;
  };

  // Update material cost
  const updateMaterialCost = (sku, newCost, vendor = '') => {
    const material = App.state.materials?.find(m => m.sku === sku);
    if (!material) return false;
    const oldCost = material.unitCost;
    material.unitCost = newCost;
    material.sellPrice = newCost * material.markup;
    material.lastUpdated = new Date().toISOString();
    if (vendor) material.vendor = vendor;
    App.saveState();
    if (newCost > oldCost * 1.1) {
      showToast(`Price alert: ${material.name} cost increased ${((newCost/oldCost - 1) * 100).toFixed(0)}%`, 'warning');
    }
    return true;
  };

  // Calculate sell price
  const calculatePrice = (data) => {
    const materialCost = data.materialCost || 0;
    const laborHours = data.laborHours || 0;
    const laborRate = data.laborRate || getDefaultLaborRate();
    const markup = data.markup || 2.0;
    const tier = data.tier || 'standard';
    const tierMultiplier = LABOR_TIERS[tier]?.multiplier || 1.0;
    const laborCost = laborHours * laborRate * tierMultiplier;
    const materialWithMarkup = materialCost * markup;
    return materialWithMarkup + laborCost;
  };

  // Get default labor rate
  const getDefaultLaborRate = () => {
    return App.state.settings?.laborRate || 125;
  };

  // Set seasonal rate
  const setSeasonalRate = (category, multiplier, season) => {
    if (!App.state.seasonalRates) App.state.seasonalRates = {};
    if (!App.state.seasonalRates[category]) App.state.seasonalRates[category] = {};
    App.state.seasonalRates[category][season] = multiplier;
    App.saveState();
  };

  // Get seasonal rate
  const getSeasonalRate = (category) => {
    const month = new Date().getMonth();
    let season = 'spring';
    if (month >= 2 && month <= 4) season = 'spring';
    else if (month >= 5 && month <= 7) season = 'summer';
    else if (month >= 8 && month <= 10) season = 'fall';
    else season = 'winter';
    return App.state.seasonalRates?.[category]?.[season] || 1.0;
  };

  // Generate SKU
  const generateSKU = (name) => {
    return name.replace(/[^A-Z0-9]/gi, '').substring(0, 8).toUpperCase() + '-' + Date.now().toString(36).toUpperCase().slice(-4);
  };

  // Get stats
  const getStats = () => {
    const materials = App.state.materials || [];
    return {
      totalMaterials: materials.length,
      avgMarkup: materials.length > 0 ?
        (materials.reduce((sum, m) => sum + m.markup, 0) / materials.length).toFixed(2) : 0,
      lowStock: materials.filter(m => m.inStock <= m.reorderPoint).length,
      categories: Object.keys(MATERIAL_CATEGORIES).length
    };
  };

  // Render settings
  const renderSettings = () => {
    const stats = getStats();
    return `
      <div class="glass-card p-6 mb-6">
        <h3 class="text-lg font-bold text-gold-400 mb-4">💰 Price Book Manager</h3>
        <div class="grid grid-cols-2 md:grid-cols-4 gap-4 mb-4">
          <div class="p-4 rounded-xl text-center" style="background:rgba(255,255,255,0.05)">
            <p class="text-3xl font-bold text-gold-400">${stats.totalMaterials}</p>
            <p class="text-sm text-gray-400">Materials</p>
          </div>
          <div class="p-4 rounded-xl text-center" style="background:rgba(255,255,255,0.05)">
            <p class="text-3xl font-bold text-blue-400">${stats.avgMarkup}x</p>
            <p class="text-sm text-gray-400">Avg Markup</p>
          </div>
          <div class="p-4 rounded-xl text-center" style="background:rgba(255,255,255,0.05)">
            <p class="text-3xl font-bold text-green-400">$${getDefaultLaborRate()}</p>
            <p class="text-sm text-gray-400">Labor Rate/hr</p>
          </div>
          <div class="p-4 rounded-xl text-center" style="background:rgba(255,255,255,0.05)">
            <p class="text-3xl font-bold text-yellow-400">${stats.lowStock}</p>
            <p class="text-sm text-gray-400">Low Stock</p>
          </div>
        </div>
        <div class="mb-4">
          <h4 class="font-semibold mb-2">Labor Rate Tiers</h4>
          <div class="grid grid-cols-2 md:grid-cols-4 gap-3">
            ${Object.entries(LABOR_TIERS).map(([key, tier]) => `
              <div class="p-3 rounded-lg text-center" style="background:rgba(255,255,255,0.05)">
                <p class="text-xl font-bold text-gold-400">${tier.multiplier}x</p>
                <p class="text-sm font-semibold">${tier.name}</p>
                <p class="text-xs text-gray-400">${tier.description}</p>
              </div>
            `).join('')}
          </div>
        </div>
        <div class="flex gap-2">
          <button onclick="PriceBookManager.showAddMaterial()" class="btn btn-primary flex-1 py-2">
            ➕ Add Material
          </button>
          <button onclick="PriceBookManager.showCalculator()" class="btn btn-secondary flex-1 py-2">
            🧮 Price Calculator
          </button>
        </div>
      </div>
    `;
  };

  // Show add material form
  const showAddMaterial = () => {
    let html = `
      <div class="space-y-4">
        <div>
          <label class="block text-sm font-medium mb-1">Material Name *</label>
          <input type="text" id="mat-name" class="form-input" placeholder="e.g., 1/2" PEX Pipe">
        </div>
        <div>
          <label class="block text-sm font-medium mb-1">Category</label>
          <select id="mat-category" class="form-input">
            ${Object.entries(MATERIAL_CATEGORIES).map(([k,v]) => `<option value="${k}">${v.icon} ${v.name}</option>`).join('')}
          </select>
        </div>
        <div class="grid grid-cols-2 gap-3">
          <div>
            <label class="block text-sm font-medium mb-1">Unit Cost ($)</label>
            <input type="number" id="mat-cost" class="form-input" placeholder="0.00" step="0.01">
          </div>
          <div>
            <label class="block text-sm font-medium mb-1">Markup (x)</label>
            <input type="number" id="mat-markup" class="form-input" value="2.0" step="0.1">
          </div>
        </div>
        <div class="grid grid-cols-2 gap-3">
          <div>
            <label class="block text-sm font-medium mb-1">Unit</label>
            <select id="mat-unit" class="form-input">
              <option value="ea">Each</option>
              <option value="ft">Foot</option>
              <option value="box">Box</option>
              <option value="case">Case</option>
              <option value="roll">Roll</option>
            </select>
          </div>
          <div>
            <label class="block text-sm font-medium mb-1">In Stock</label>
            <input type="number" id="mat-stock" class="form-input" value="0">
          </div>
        </div>
        <button onclick="PriceBookManager.addMaterialFromForm()" class="btn btn-primary w-full py-2">
          Add Material
        </button>
      </div>`;
    App.showModal('Add Material', html);
  };

  // Add material from form
  const addMaterialFromForm = () => {
    const name = document.getElementById('mat-name')?.value?.trim();
    if (!name) {
      showToast('Material name is required', 'warning');
      return;
    }
    const cost = parseFloat(document.getElementById('mat-cost')?.value) || 0;
    const markup = parseFloat(document.getElementById('mat-markup')?.value) || 2.0;
    addMaterial({
      name: name,
      category: document.getElementById('mat-category')?.value,
      unitCost: cost,
      markup: markup,
      sellPrice: cost * markup,
      unit: document.getElementById('mat-unit')?.value,
      inStock: parseInt(document.getElementById('mat-stock')?.value) || 0
    });
    App.closeModal();
    showToast('Material added', 'success');
  };

  // Show calculator
  const showCalculator = () => {
    let html = `
      <div class="space-y-4">
        <div>
          <label class="block text-sm font-medium mb-1">Material Cost ($)</label>
          <input type="number" id="calc-material" class="form-input" placeholder="0.00" step="0.01" oninput="PriceBookManager.updateCalculator()">
        </div>
        <div>
          <label class="block text-sm font-medium mb-1">Labor Hours</label>
          <input type="number" id="calc-hours" class="form-input" placeholder="0" step="0.5" oninput="PriceBookManager.updateCalculator()">
        </div>
        <div>
          <label class="block text-sm font-medium mb-1">Labor Tier</label>
          <select id="calc-tier" class="form-input" onchange="PriceBookManager.updateCalculator()">
            ${Object.entries(LABOR_TIERS).map(([k,v]) => `<option value="${k}">${v.name} (${v.multiplier}x)</option>`).join('')}
          </select>
        </div>
        <div class="p-4 rounded-xl text-center" style="background:rgba(255,215,0,0.1);border:1px solid rgba(255,215,0,0.3)">
          <p class="text-sm text-gray-400">Estimated Price</p>
          <p id="calc-result" class="text-3xl font-bold text-gold-400">$0.00</p>
        </div>
      </div>`;
    App.showModal('Price Calculator', html);
  };

  // Update calculator
  const updateCalculator = () => {
    const material = parseFloat(document.getElementById('calc-material')?.value) || 0;
    const hours = parseFloat(document.getElementById('calc-hours')?.value) || 0;
    const tier = document.getElementById('calc-tier')?.value || 'standard';
    const price = calculatePrice({
      materialCost: material,
      laborHours: hours,
      tier: tier
    });
    const el = document.getElementById('calc-result');
    if (el) el.textContent = `$${price.toFixed(2)}`;
  };

  return {
    MATERIAL_CATEGORIES,
    LABOR_TIERS,
    addMaterial,
    updateMaterialCost,
    calculatePrice,
    getDefaultLaborRate,
    setSeasonalRate,
    getSeasonalRate,
    getStats,
    renderSettings,
    showAddMaterial,
    addMaterialFromForm,
    showCalculator,
    updateCalculator
  };
})();

modules/review-reputation.js.content:
/* ============================================
   REVIEW REPUTATION — FlowJob
   Review solicitation, tracking, response
   ============================================ */
const ReviewReputation = (() => {
  // Review platforms
  const PLATFORMS = {
    google: { name: 'Google', color: '#4285F4', icon: '🔵' },
    yelp: { name: 'Yelp', color: '#D32323', icon: '🔴' },
    facebook: { name: 'Facebook', color: '#1877F2', icon: '🔵' },
    angi: { name: 'Angi', color: '#76B82A', icon: '🟢' },
    thumbtack: { name: 'Thumbtack', color: '#00B8D4', icon: '🔵' }
  };

  // Response templates
  const RESPONSE_TEMPLATES = {
    positive: [
      "Thank you for your kind words! We're glad we could help with your plumbing needs. We look forward to serving you again!",
      "We appreciate your feedback! It was a pleasure working with you. Don't hesitate to reach out if you need anything else.",
      "Thank you for the wonderful review! We're committed to providing top-quality service to all our customers."
    ],
    negative: [
      "We're sorry to hear about your experience. We take all feedback seriously and would like to make this right. Please contact us directly so we can address your concerns.",
      "Thank you for bringing this to our attention. We apologize for any inconvenience and would appreciate the opportunity to discuss this further. Please reach out to us at your convenience.",
      "We're disappointed to hear we didn't meet your expectations. Your feedback helps us improve. Please contact us so we can resolve this matter."
    ],
    neutral: [
      "Thank you for your feedback! We're always working to improve our services. If there's anything we can do better, please let us know.",
      "We appreciate you taking the time to review us. Your input helps us serve our customers better."
    ]
  };

  // Request review via SMS/Email
  const requestReview = async (jobId, method = 'sms') => {
    const job = App.state.jobs?.find(j => j.id === jobId);
    if (!job) {
      showToast('Job not found', 'error');
      return false;
    }
    const customer = App.state.customers?.find(c => c.name === job.customer);
    const contact = method === 'sms' ? customer?.phone : customer?.email;
    if (!contact) {
      showToast(`Customer ${method === 'sms' ? 'phone' : 'email'} not found`, 'error');
      return false;
    }
    const message = generateReviewMessage(job, customer);
    // Track request
    if (!App.state.reviewRequests) App.state.reviewRequests = [];
    App.state.reviewRequests.push({
      id: Date.now(),
      jobId: jobId,
      customerId: customer?.id,
      method: method,
      contact: contact,
      sentAt: new Date().toISOString(),
      status: 'sent'
    });
    App.saveState();
    // In production, this would call Twilio/SendGrid API
    showToast(`Review request sent via ${method.toUpperCase()}`, 'success');
    return true;
  };

  // Generate review message
  const generateReviewMessage = (job, customer) => {
    const businessName = App.state.settings?.businessName || 'FlowJob';
    const reviewLinks = {
      google: App.state.settings?.googleReviewLink || '#',
      yelp: App.state.settings?.yelpReviewLink || '#'
    };
    return `Hi ${customer?.name || 'there'}! Thank you for choosing ${businessName} for your recent ${job.title || 'service'}. We hope you're satisfied with our work! If you have a moment, we'd greatly appreciate a review: ${reviewLinks.google || reviewLinks.yelp}. Your feedback helps us serve you better!`;
  };

  // Track review
  const trackReview = (review) => {
    if (!App.state.reviews) App.state.reviews = [];
    App.state.reviews.push({
      id: Date.now(),
      ...review,
      date: review.date || new Date().toISOString(),
      responded: false
    });
    App.saveState();
    return true;
  };

  // Get average rating
  const getAverageRating = (platform = null) => {
    const reviews = (App.state.reviews || []).filter(r => !platform || r.platform === platform);
    if (reviews.length === 0) return 0;
    const sum = reviews.reduce((acc, r) => acc + (r.rating || 0), 0);
    return (sum / reviews.length).toFixed(1);
  };

  // Get review stats
  const getStats = () => {
    const reviews = App.state.reviews || [];
    const total = reviews.length;
    const byRating = { 5: 0, 4: 0, 3: 0, 2: 0, 1: 0 };
    reviews.forEach(r => { if (byRating[r.rating] !== undefined) byRating[r.rating]++; });
    const byPlatform = {};
    Object.keys(PLATFORMS).forEach(p => {
      byPlatform[p] = reviews.filter(r => r.platform === p).length;
    });
    const unresponded = reviews.filter(r => !r.responded && r.rating <= 3).length;
    return { total, byRating, byPlatform, unresponded, average: getAverageRating() };
  };

  // Get response template
  const getResponseTemplate = (rating, customText = '') => {
    let category = 'neutral';
    if (rating >= 4) category = 'positive';
    else if (rating <= 2) category = 'negative';
    const templates = RESPONSE_TEMPLATES[category];
    const template = templates[Math.floor(Math.random() * templates.length)];
    return customText ? `${customText}\n\n${template}` : template;
  };

  // Mark review as responded
  const markResponded = (reviewId) => {
    const review = App.state.reviews?.find(r => r.id === reviewId);
    if (review) {
      review.responded = true;
      review.respondedAt = new Date().toISOString();
      App.saveState();
    }
  };

  // Render review settings
  const renderSettings = () => {
    const stats = getStats();
    return `
      <div class="glass-card p-6 mb-6">
        <h3 class="text-lg font-bold text-gold-400 mb-4">⭐ Review Reputation</h3>
        <div class="grid grid-cols-2 md:grid-cols-4 gap-4 mb-4">
          <div class="p-4 rounded-xl text-center" style="background:rgba(255,255,255,0.05)">
            <p class="text-3xl font-bold text-gold-400">${stats.average}</p>
            <p class="text-sm text-gray-400">Avg Rating</p>
          </div>
          <div class="p-4 rounded-xl text-center" style="background:rgba(255,255,255,0.05)">
            <p class="text-3xl font-bold">${stats.total}</p>
            <p class="text-sm text-gray-400">Total Reviews</p>
          </div>
          <div class="p-4 rounded-xl text-center" style="background:rgba(255,255,255,0.05)">
            <p class="text-3xl font-bold text-yellow-400">${stats.unresponded}</p>
            <p class="text-sm text-gray-400">Need Response</p>
          </div>
          <div class="p-4 rounded-xl text-center" style="background:rgba(255,255,255,0.05)">
            <p class="text-3xl font-bold text-blue-400">${Object.values(stats.byPlatform).reduce((a,b) => a+b, 0)}</p>
            <p class="text-sm text-gray-400">Platforms</p>
          </div>
        </div>
        <div class="mb-4">
          <label class="block text-sm font-medium mb-1">Google Review Link</label>
          <input type="url" id="google_review_link" value="${App.esc(App.state.settings?.googleReviewLink || '')}"
                 class="form-input" placeholder="https://g.page/r/..."
                 onchange="ReviewReputation.saveLink('google', this.value)">
        </div>
        <div class="mb-4">
          <label class="block text-sm font-medium mb-1">Yelp Review Link</label>
          <input type="url" id="yelp_review_link" value="${App.esc(App.state.settings?.yelpReviewLink || '')}"
                 class="form-input" placeholder="https://yelp.com/biz/..."
                 onchange="ReviewReputation.saveLink('yelp', this.value)">
        </div>
        <div class="flex gap-2">
          <button onclick="ReviewReputation.showRecentReviews()" class="btn btn-secondary text-sm px-4 py-2">
            📋 View Recent Reviews
          </button>
          <button onclick="ReviewReputation.exportReviews()" class="btn btn-secondary text-sm px-4 py-2">
            📥 Export Reviews
          </button>
        </div>
      </div>
    `;
  };

  // Save review link
  const saveLink = (platform, url) => {
    App.state.settings = App.state.settings || {};
    App.state.settings[`${platform}ReviewLink`] = url;
    App.saveState();
    showToast(`${PLATFORMS[platform].name} review link saved`, 'success');
  };

  // Show recent reviews
  const showRecentReviews = () => {
    const reviews = (App.state.reviews || []).sort((a,b) => new Date(b.date) - new Date(a.date)).slice(0, 20);
    if (reviews.length === 0) {
      showToast('No reviews yet', 'info');
      return;
    }
    let html = '<div class="space-y-3 max-h-96 overflow-y-auto">';
    reviews.forEach(r => {
      const platform = PLATFORMS[r.platform] || { name: r.platform, icon: '⭐' };
      const stars = '⭐'.repeat(r.rating || 0);
      html += `
        <div class="p-3 rounded-lg" style="background:rgba(255,255,255,0.05)">
          <div class="flex justify-between items-start">
            <div>
              <span class="font-semibold">${platform.icon} ${platform.name}</span>
              <span class="ml-2">${stars}</span>
            </div>
            <span class="text-xs text-gray-400">${new Date(r.date).toLocaleDateString()}</span>
          </div>
          <p class="text-sm mt-1">${App.esc(r.text || '')}</p>
          ${!r.responded ? `<button onclick="ReviewReputation.markResponded(${r.id})" class="text-xs text-blue-400 mt-1">Mark as Responded</button>` : '<span class="text-xs text-green-400">✓ Responded</span>'}
        </div>`;
    });
    html += '</div>';
    App.showModal('Recent Reviews', html);
  };

  // Export reviews
  const exportReviews = () => {
    const reviews = App.state.reviews || [];
    if (reviews.length === 0) {
      showToast('No reviews to export', 'info');
      return;
    }
    const rows = [['Date', 'Platform', 'Rating', 'Review', 'Customer', 'Responded']];
    reviews.forEach(r => {
      rows.push([
        new Date(r.date).toLocaleDateString(),
        r.platform || '',
        r.rating || '',
        `"${(r.text || '').replace(/"/g, '""')}"`,
        r.customerName || '',
        r.responded ? 'Yes' : 'No'
      ]);
    });
    const csv = rows.map(r => r.join(',')).join('\n');
    download(csv, `FlowJob_Reviews_${new Date().toISOString().split('T')[0]}.csv`, 'text/csv');
  };

  return {
    requestReview,
    trackReview,
    getAverageRating,
    getStats,
    getResponseTemplate,
    markResponded,
    renderSettings,
    saveLink,
    showRecentReviews,
    exportReviews
  };
})();

