// Service History Module — Complete job history per customer
// Shows every quote, invoice, warranty, and service call in one timeline

Pages.serviceHistory = function() {
  const customers = App.state.customers || [];

  return `
    <div class="page-header">
      <h2>📋 Service History</h2>
      <p>Complete history per customer — every job, quote, invoice, and warranty</p>
    </div>
    <div style="display:flex;gap:12px;margin-bottom:16px;flex-wrap:wrap;align-items:center">
      <select class="form-control" id="sh-customer" onchange="ServiceHistory.load(this.value)" style="max-width:300px">
        <option value="">— Select a customer —</option>
        ${customers.map(c => `<option value="${c.name}">${c.name}${c.address?' — '+c.address:''}</option>`).join('')}
      </select>
      <input class="form-control" id="sh-search" placeholder="Search customers..." style="max-width:250px" oninput="ServiceHistory._search(this.value)">
    </div>
    <div id="sh-content">
      <div class="card"><div class="empty-state"><div class="icon">📋</div><h3>Select a customer</h3><p>View their complete service history, quotes, invoices, and warranties in one place</p></div></div>
    </div>`;
};

const ServiceHistory = {
  _search(q) {
    q = q.toLowerCase();
    const sel = document.getElementById('sh-customer');
    if (!sel) return;
    for (let i = 0; i < sel.options.length; i++) {
      const opt = sel.options[i];
      if (i === 0) continue; // skip placeholder
      opt.style.display = opt.text.toLowerCase().includes(q) ? '' : 'none';
    }
  },

  load(customerName) {
    if (!customerName) return;
    const el = document.getElementById('sh-content');

    // Gather all data for this customer
    const quotes = (App.state.quotes||[]).filter(q => q.customer === customerName).sort((a,b) => b.date.localeCompare(a.date));
    const invoices = (App.state.invoices||[]).filter(i => i.customer === customerName).sort((a,b) => b.date.localeCompare(a.date));
    const warranties = (App.state.warranties||[]).filter(w => w.customer === customerName).sort((a,b) => b.jobDate.localeCompare(a.jobDate));
    const customer = (App.state.customers||[]).find(c => c.name === customerName);

    // Calculate totals
    const totalSpent = invoices.filter(i => i.status === 'paid').reduce((s,i) => s + i.total, 0);
    const totalQuotes = quotes.length;
    const totalInvoices = invoices.length;
    const activeWarranties = warranties.filter(w => new Date(w.expiryDate) >= new Date()).length;

    // Build timeline
    const timeline = [];
    quotes.forEach(q => timeline.push({ date: q.date, type: 'quote', data: q, icon: '📋' }));
    invoices.forEach(i => timeline.push({ date: i.date, type: 'invoice', data: i, icon: '💰' }));
    warranties.forEach(w => timeline.push({ date: w.jobDate, type: 'warranty', data: w, icon: '🛡️' }));
    timeline.sort((a,b) => b.date.localeCompare(a.date));

    el.innerHTML = `
      <!-- Customer Info Card -->
      ${customer ? `<div class="card" style="margin-bottom:16px">
        <div style="display:flex;justify-content:space-between;align-items:start;flex-wrap:wrap;gap:12px">
          <div>
            <h3 style="margin:0">${customer.name}</h3>
            <p style="color:var(--text-muted);margin:4px 0">${customer.phone||''} ${customer.email?'· '+customer.email:''}</p>
            ${customer.address ? `<p style="color:var(--text-muted);font-size:13px">${customer.address}</p>` : ''}
          </div>
          <div style="display:flex;gap:16px;text-align:center">
            <div><div style="font-size:20px;font-weight:700;color:var(--navy)">${App.formatCurrency(totalSpent)}</div><div style="font-size:11px;color:var(--text-muted)">Total Spent</div></div>
            <div><div style="font-size:20px;font-weight:700">${totalInvoices}</div><div style="font-size:11px;color:var(--text-muted)">Jobs</div></div>
            <div><div style="font-size:20px;font-weight:700;color:var(--success)">${activeWarranties}</div><div style="font-size:11px;color:var(--text-muted)">Active Warranties</div></div>
          </div>
        </div>
      </div>` : ''}

      <!-- Quick Stats -->
      <div class="grid grid-4" style="margin-bottom:16px">
        <div class="stat-card"><div class="stat-value">${totalQuotes}</div><div class="stat-label">Quotes</div></div>
        <div class="stat-card"><div class="stat-value">${totalInvoices}</div><div class="stat-label">Invoices</div></div>
        <div class="stat-card"><div class="stat-value">${warranties.length}</div><div class="stat-label">Warranties</div></div>
        <div class="stat-card"><div class="stat-value">${quotes.filter(q=>q.status==='pending').length + invoices.filter(i=>i.status==='unpaid').length}</div><div class="stat-label">Pending Action</div></div>
      </div>

      <!-- Timeline -->
      <div class="card">
        <h3 style="margin-bottom:16px">📅 Timeline</h3>
        ${timeline.length === 0 
          ? '<p style="color:var(--text-muted)">No history found for this customer.</p>'
          : `<div style="position:relative;padding-left:24px">
            <div style="position:absolute;left:8px;top:0;bottom:0;width:2px;background:var(--border)"></div>
            ${timeline.map(t => {
              const d = t.data;
              let content = '';
              if (t.type === 'quote') {
                content = `<strong>📋 Quote #${d.number}</strong> — ${App.formatCurrency(d.total)} 
                  <span class="badge badge-${d.status==='accepted'?'success':'warning'}">${d.status}</span><br>
                  <small>${d.items.length} items${d.notes?' · '+d.notes.substring(0,60):''}</small>`;
              } else if (t.type === 'invoice') {
                content = `<strong>💰 Invoice #${d.number}</strong> — ${App.formatCurrency(d.total)} 
                  <span class="badge badge-${d.status==='paid'?'success':d.status==='overdue'?'danger':'warning'}">${d.status}</span>
                  ${d.paymentMethod?'<small> via '+d.paymentMethod+'</small>':''}`;
              } else if (t.type === 'warranty') {
                const daysLeft = Math.ceil((new Date(d.expiryDate) - new Date()) / 86400000);
                content = `<strong>🛡️ Warranty</strong> — ${d.type==='labor'?'Labor':'Parts'}: ${d.description||'—'} 
                  <span class="badge badge-${daysLeft>30?'success':daysLeft>0?'warning':'danger'}">${daysLeft>0?daysLeft+'d left':'Expired'}</span>`;
              }
              return `<div style="position:relative;margin-bottom:16px;padding-left:16px">
                <div style="position:absolute;left:-20px;top:6px;width:12px;height:12px;border-radius:50%;background:var(--primary);border:2px solid var(--card-bg,#fff)"></div>
                <div style="font-size:11px;color:var(--text-muted);margin-bottom:2px">${App.formatDate(t.date)}</div>
                <div style="font-size:13px">${content}</div>
              </div>`;
            }).join('')}
          </div>`}
      </div>`;
  }
};

modules/warranty-tracker.js.content:
// Warranty Tracker Module — Track labor & parts warranties per job
// Auto-calculates expiry dates, alerts when warranties expire soon

Pages.warrantyTracker = function() {
  const warranties = App.state.warranties || [];
  const today = new Date();

  // Categorize
  const active = warranties.filter(w => new Date(w.expiryDate) >= today);
  const expiringSoon = active.filter(w => {
    const daysLeft = Math.ceil((new Date(w.expiryDate) - today) / 86400000);
    return daysLeft <= 30;
  });
  const expired = warranties.filter(w => new Date(w.expiryDate) < today);

  return `
    <div class="page-header">
      <h2>🛡️ Warranty Tracker</h2>
      <p>Track labor and parts warranties for all jobs</p>
    </div>
    <div style="display:flex;gap:12px;margin-bottom:16px;flex-wrap:wrap;align-items:center">
      <button class="btn btn-primary" onclick="WarrantyTracker.new()">+ Add Warranty</button>
      <input class="form-control" id="warranty-search" placeholder="Search warranties..." style="max-width:250px" oninput="WarrantyTracker._filter()">
      <select class="form-control" id="warranty-status-filter" style="max-width:160px" onchange="WarrantyTracker._filter()">
        <option value="">All</option>
        <option value="active">✅ Active</option>
        <option value="expiring">⚠️ Expiring Soon (30d)</option>
        <option value="expired">❌ Expired</option>
      </select>
    </div>

    <!-- Stats -->
    <div class="grid grid-4" style="margin-bottom:16px">
      <div class="stat-card"><div class="stat-value">${active.length}</div><div class="stat-label">Active</div></div>
      <div class="stat-card"><div class="stat-value" style="color:var(--warning,#e5a500)">${expiringSoon.length}</div><div class="stat-label">Expiring Soon</div></div>
      <div class="stat-card"><div class="stat-value" style="color:var(--danger,#dc3545)">${expired.length}</div><div class="stat-label">Expired</div></div>
      <div class="stat-card"><div class="stat-value">${warranties.length}</div><div class="stat-label">Total</div></div>
    </div>

    ${warranties.length === 0
      ? '<div class="card"><div class="empty-state"><div class="icon">🛡️</div><h3>No warranties tracked yet</h3><p>Add warranties to protect your work and your customers</p></div></div>'
      : `<div class="card"><div class="table-wrap"><table>
        <thead><tr><th>Customer</th><th>Type</th><th>Description</th><th>Job Date</th><th>Expires</th><th>Days Left</th><th>Status</th><th></th></tr></thead>
        <tbody>${warranties.map(w => {
          const expiry = new Date(w.expiryDate);
          const daysLeft = Math.ceil((expiry - today) / 86400000);
          const status = daysLeft < 0 ? 'expired' : daysLeft <= 30 ? 'expiring' : 'active';
          return `<tr class="warranty-row" data-customer="${(w.customer||'').toLowerCase()}" data-status="${status}" data-search="${(w.customer+' '+w.description+' '+w.type).toLowerCase()}">
            <td>${w.customer||'—'}</td>
            <td><span class="badge badge-${w.type==='labor'?'info':'warning'}">${w.type==='labor'?'🔧 Labor':'🔩 Parts'}</span></td>
            <td>${w.description||'—'}</td>
            <td>${App.formatDate(w.jobDate)}</td>
            <td>${App.formatDate(w.expiryDate)}</td>
            <td style="font-weight:600;color:${daysLeft<0?'var(--danger)':daysLeft<=30?'var(--warning,#e5a500)':'var(--success)'}">${daysLeft < 0 ? Math.abs(daysLeft) + 'd ago' : daysLeft + 'd'}</td>
            <td><span class="badge badge-${status==='active'?'success':status==='expiring'?'warning':'danger'}">${status==='active'?'Active':status==='expiring'?'Expiring':'Expired'}</span></td>
            <td style="white-space:nowrap"><button class="btn btn-sm btn-outline" onclick="WarrantyTracker.view('${w.id}')">View</button>
              <button class="btn btn-sm btn-danger" onclick="WarrantyTracker.remove('${w.id}')">✕</button></td>
          </tr>`;
        }).join('')}</tbody>
      </table></div></div>`}`;
};

PageInit.warrantyTracker = function() { WarrantyTracker._filter(); };

const WarrantyTracker = {
  _filter() {
    const q = (document.getElementById('warranty-search')?.value || '').toLowerCase();
    const status = document.getElementById('warranty-status-filter')?.value || '';
    document.querySelectorAll('.warranty-row').forEach(row => {
      const matchText = row.dataset.search.includes(q);
      const matchStatus = !status || row.dataset.status === status;
      row.style.display = (matchText && matchStatus) ? '' : 'none';
    });
  },

  new() {
    App.openModal(`
      <div class="modal-header"><h3>Add Warranty</h3><button class="modal-close" onclick="App.closeModal()">✕</button></div>
      <div class="form-group"><label>Customer</label>
        <select class="form-control" id="wt-cust-select" onchange="document.getElementById('wt-cust').value=this.value">
          <option value="">— Select or type below —</option>
          ${(App.state.customers||[]).map(c => `<option value="${c.name}">${c.name}</option>`).join('')}
        </select>
        <input class="form-control" id="wt-cust" placeholder="Customer name" style="margin-top:6px">
      </div>
      <div class="form-group"><label>Warranty Type</label>
        <select class="form-control" id="wt-type">
          <option value="labor">🔧 Labor Warranty</option>
          <option value="parts">🔩 Parts/Equipment Warranty</option>
        </select></div>
      <div class="form-group"><label>Description</label>
        <input class="form-control" id="wt-desc" placeholder="e.g. Water heater installation, Bathroom rough-in"></div>
      <div class="form-group"><label>Job/Service Date</label>
        <input class="form-control" type="date" id="wt-job-date" value="${App.today()}"></div>
      <div class="form-group"><label>Warranty Period</label>
        <div style="display:flex;gap:8px;align-items:center">
          <input class="form-control" type="number" id="wt-period" value="12" style="width:80px">
          <select class="form-control" id="wt-unit" style="width:100px">
            <option value="months">Months</option>
            <option value="years">Years</option>
          </select>
          <span style="font-size:12px;color:var(--text-muted)">Standard: 1 year labor, varies for parts</span>
        </div>
      </div>
      <div class="form-group"><label>Notes</label>
        <textarea class="form-control" id="wt-notes" placeholder="Conditions, exclusions, serial numbers..."></textarea></div>
      <div class="modal-footer">
        <button class="btn btn-outline" onclick="App.closeModal()">Cancel</button>
        <button class="btn btn-primary" onclick="WarrantyTracker._saveNew()">Add Warranty</button>
      </div>
    `);
  },

  _saveNew() {
    const customer = document.getElementById('wt-cust').value.trim();
    if (!customer) return App.toast('Customer name required', 'error');
    const type = document.getElementById('wt-type').value;
    const jobDate = document.getElementById('wt-job-date').value;
    const period = parseInt(document.getElementById('wt-period').value) || 12;
    const unit = document.getElementById('wt-unit').value;

    // Calculate expiry
    const expiry = new Date(jobDate);
    if (unit === 'years') expiry.setFullYear(expiry.getFullYear() + period);
    else expiry.setMonth(expiry.getMonth() + period);

    if (!App.state.warranties) App.state.warranties = [];
    App.state.warranties.push({
      id: App.genId(),
      customer,
      type,
      description: document.getElementById('wt-desc').value.trim(),
      jobDate,
      warrantyPeriod: period,
      warrantyUnit: unit,
      expiryDate: expiry.toISOString().slice(0, 10),
      notes: document.getElementById('wt-notes').value.trim(),
      status: 'active',
      createdAt: App.today()
    });
    App.saveState(); App.closeModal(); App.handleRoute();
    App.toast('Warranty added');
  },

  view(id) {
    const w = (App.state.warranties||[]).find(x => x.id === id);
    if (!w) return;
    const today = new Date();
    const daysLeft = Math.ceil((new Date(w.expiryDate) - today) / 86400000);
    App.openModal(`
      <div class="modal-header"><h3>Warranty Details</h3><button class="modal-close" onclick="App.closeModal()">✕</button></div>
      <div style="padding:16px 0">
        <p><strong>Customer:</strong> ${w.customer}</p>
        <p><strong>Type:</strong> ${w.type === 'labor' ? '🔧 Labor' : '🔩 Parts/Equipment'}</p>
        <p><strong>Description:</strong> ${w.description || '—'}</p>
        <p><strong>Job Date:</strong> ${App.formatDate(w.jobDate)}</p>
        <p><strong>Warranty Period:</strong> ${w.warrantyPeriod} ${w.warrantyUnit}</p>
        <p><strong>Expires:</strong> ${App.formatDate(w.expiryDate)}</p>
        <p><strong>Status:</strong> <span style="font-weight:700;color:${daysLeft<0?'var(--danger)':daysLeft<=30?'var(--warning,#e5a500)':'var(--success)'}">
          ${daysLeft < 0 ? '❌ Expired ' + Math.abs(daysLeft) + ' days ago' : daysLeft <= 30 ? '⚠️ Expiring in ' + daysLeft + ' days' : '✅ Active — ' + daysLeft + ' days remaining'}
        </span></p>
        ${w.notes ? '<p><strong>Notes:</strong><br>' + w.notes + '</p>' : ''}
      </div>
      <div class="modal-footer">
        ${daysLeft > 0 ? `<button class="btn btn-primary" onclick="WarrantyTracker._extend('${w.id}')">🔄 Extend Warranty</button>` : ''}
        <button class="btn btn-outline" onclick="App.closeModal()">Close</button>
      </div>
    `);
  },

  _extend(id) {
    const w = (App.state.warranties||[]).find(x => x.id === id);
    if (!w) return;
    // Extend by original period
    const expiry = new Date(w.expiryDate);
    if (w.warrantyUnit === 'years') expiry.setFullYear(expiry.getFullYear() + w.warrantyPeriod);
    else expiry.setMonth(expiry.getMonth() + w.warrantyPeriod);
    w.expiryDate = expiry.toISOString().slice(0, 10);
    App.saveState(); App.closeModal(); App.handleRoute();
    App.toast('Warranty extended by ' + w.warrantyPeriod + ' ' + w.warrantyUnit);
  },

  async remove(id) {
    if (await App.confirm('Delete this warranty?')) {
      App.state.warranties = (App.state.warranties||[]).filter(w => w.id !== id);
      App.saveState(); App.handleRoute(); App.toast('Warranty deleted');
    }
  }
};
